mapper.select:
select case when a.target_user_id !=0 and a.target_user_id is not null then a.event_id || '_others_' || a.state else a.event_id || '_my' end numKey,count(1) as num from( select eventRes.*, case when eventRes.user_id!=#{userId} then mm.read_state else null end state from gc_user_event_resource eventRes LEFT JOIN gc_master_message mm on mm.res_id = eventRes.id
LEFT JOIN gc_event gcEvent ON eventRes.event_id = gcEvent.id LEFT JOIN gc_video gcVideo ON gcVideo.id = gcEvent.video_id LEFT JOIN gc_subject sub on sub.id=gcVideo.sub_id
where sub.id = #{subId} and (eventRes.target_user_id=#{userId} or eventRes.user_id=#{userId}) group by eventRes.id, mm.read_state
) a group by COALESCE(a.state, 1), a.target_user_id, a.event_id, a.state;

select
	case when  a.target_user_id !=0 and a.target_user_id is not null then a.event_id || '_my'
		 else a.event_id || '_others_' || a.state end numKey,count(1) as num
from(
		select  eventRes.*
			 ,gcEvent.event_title
			 , mm.read_state,
			case when eventRes.user_id!=#{teacherId} and mm.read_state is null then 1 else mm.read_state end state
		from gc_user_event_resource eventRes
				 LEFT JOIN gc_master_message mm on mm.res_id = eventRes.id AND (mm.target_user_id = eventRes.target_user_id or eventRes.target_user_id is null) and mm.target_user_id=#{teacherId}
				 LEFT JOIN gc_event gcEvent ON eventRes.event_id = gcEvent.id
				 LEFT JOIN gc_video gcVideo ON gcVideo.id = gcEvent.video_id
				 LEFT JOIN gc_subject sub on sub.id=gcVideo.sub_id
		where sub.id = #{subId}
		  and (
				(eventRes.user_id=#{teacherId} and eventRes.target_user_id=#{studentId}) or
				(eventRes.user_id=#{studentId})
			)
		group by eventRes.id, gcEvent.event_title, mm.read_state
	) a group by COALESCE(a.state, 1), a.target_user_id, a.event_id, a.state;

SELECT


,concat('[',string_agg(tags.tag_text, ','),']') as course_tags
FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
left join gc_subject_tags tags on tags.subject_id = s.id and ((tags.master_id = #{masterId}) or (tags.master_id != #{masterId} and tags.type = 1))
WHERE s.master_id = #{masterId}

	AND s.level = #{level}


	AND s.state = #{state}

GROUP BY s.id, f.id
ORDER BY s.order ASC,s.create_time desc,s.id

select DISTINCT ON (s.id) s2.num as subjectsSize, vnum.videoNum as videosTotalNum, s.id, s.master_id, s.name, s.name_index, s.description, s.sub_id, s.type, s.level, s.fid, s.order, s.sub_img_id, s.template_id, s.intro_on_off, s.update_time, s.create_time ,s.state, s.token, s.is_public, s.cate_id ,s.language, s.certificates_flag, s.course_tagline, s.cpd_hours, s.badge_id, s.subdetail_img_id, s.badge_content, s.create_user, s.available_type ,f.id as f_id, f.name as f_name, f.file_url as f_file_url, f.save_type as f_save_type from ( select count(case when b.play_state=1 then 1 end) as nums, b.* from( SELECT max(p.play_state) as play_state, a.id, a.user_id, a.info_id, a.master_id, a.name, a.name_index, a.description, a.type, a.sub_id, a.level, a.fid, a.alias_sub_id, a."order", a.sub_img_id, a.state, a.token, a.is_public, a.master_type_id::jsonb, a.template_id, a.intro_on_off, a.update_time, a.create_time, a.cate_id, a.language, a.certificates_flag, a.course_tagline, a.cpd_hours, a.badge_id, a.subdetail_img_id::jsonb, a.badge_content, a.create_user, a.available_type FROM (SELECT u.id AS user_id, u.info_id AS info_id, s.*, v.id as video_id, v."video_name" FROM gc_subject s
LEFT JOIN gc_content_group_course_assignment course_assignment ON course_assignment.course_id = s.id LEFT JOIN gc_access content_group ON course_assignment.content_group_id = content_group.id
LEFT JOIN gc_content_group_course_assignment course_assignment ON course_assignment.course_id = s.id AND course_assignment.is_mandatory = 1 LEFT JOIN gc_access content_group ON course_assignment.content_group_id = content_group.id
LEFT JOIN gc_content_group_course_assignment course_assignment ON course_assignment.course_id = s.id AND course_assignment.is_mandatory = 0
and s.id not in
${subIdList}
LEFT JOIN gc_access content_group ON course_assignment.content_group_id = content_group.id
LEFT JOIN gc_content_group_course_assignment course_assignment ON course_assignment.course_id = s.id LEFT JOIN gc_access content_group ON course_assignment.content_group_id = content_group.id
LEFT JOIN gc_user_access ua ON ua.access_id = content_group.id LEFT JOIN gc_user u ON u.id = ua.user_id LEFT JOIN gc_subject s2 ON s2.fid = s.id LEFT JOIN gc_video v ON v.sub_id = s2.id WHERE 1 = 1
and u.id = #{userId}
AND ua.master_id = #{masterId} AND u.id = #{userId}
and s.master_id = #{masterId} AND s.state = #{state} and ua.role_json::text like concat('%','groupMember','%')
or (s.create_user = #{userId} and s.master_id = #{masterId} and s.state = #{state})
or s.available_type = 1
and s.id not in
${subIdList}
and s.master_id= #{masterId}
GROUP BY v.id, u.id, s.id ) AS a LEFT JOIN gc_user_video_play p ON p.video_id = a.video_id AND p.user_id = a.user_id AND p.play_state = 1 AND p.play_state IS NOT NULL GROUP BY a.id, a.user_id, p.video_id, a.info_id, a.master_id, a.name, a.name_index, a.description, a.type, a.sub_id, a.level, a.fid, a.alias_sub_id, a."order", a.sub_img_id, a.state, a.token, a.is_public, a.master_type_id::jsonb, a.template_id, a.intro_on_off, a.update_time, a.create_time, a.cate_id, a.language, a.certificates_flag, a.course_tagline, a.cpd_hours, a.badge_id, a.subdetail_img_id::jsonb, a.badge_content, a.create_user, a.available_type) as b
where b.name like CONCAT('%',#{subjectName},'%')
GROUP BY b.id, b.user_id, b.play_state, b.info_id, b.master_id, b.name, b.name_index, b.description, b.type, b.sub_id, b.level, b.fid, b.alias_sub_id, b."order", b.sub_img_id, b.state, b.token, b.is_public, b.master_type_id::jsonb, b.template_id, b.intro_on_off, b.update_time, b.create_time, b.cate_id, b.language, b.certificates_flag, b.course_tagline, b.cpd_hours, b.badge_id, b.subdetail_img_id::jsonb, b.badge_content, b.create_user, b.available_type) as s left join sys_file f on s.sub_img_id=f.id left join gc_subject sub1 on sub1.fid = s.id left join gc_video v on v.sub_id = sub1.id
left join (select count(v.id) as videoNum,s.id as id from gc_subject s left join gc_subject s2 on s2.fid = s.id left join gc_video v on v.sub_id = s2.id GROUP BY s.id ) vNum on
vNum.videoNum = s.nums and
s.id = vNum.id left join ( select count(*)as num,fid from gc_subject where "level" = 1 GROUP BY fid ) s2 on s2.fid = s.id left join (SELECT * FROM (SELECT sum(CASE WHEN answer_json IS NULL THEN 0 ELSE 1 END) AS anNums, sum(CASE WHEN event_nums.event_id IS NULL THEN 0 ELSE 1 END) AS eventNums, event_nums.* FROM ( SELECT an.answer_json::jsonb, u.id AS user_id, e.id AS event_id, s.id AS subject_id FROM gc_subject s LEFT JOIN gc_subject s2 ON s.id = s2.fid LEFT JOIN gc_video v ON v.sub_id = s2.id LEFT JOIN gc_event e ON e.video_id = v.id LEFT JOIN gc_user u ON u.id = #{userId} LEFT JOIN gc_user_event ue ON ue.event_id = e.id AND ue.user_id = u.id AND ue.master_id = #{masterId} LEFT JOIN gc_user_answer an ON an.event_id = e.id AND an.user_id = u.id AND an.master_id = #{masterId} AND (( e.upload_type = 2 AND ue.id IS NOT NULL ) OR ( e.upload_type = 1 ) OR ( e.upload_type IS NULL AND e.id IS NULL ) ) ) event_nums GROUP BY event_nums.user_id, event_nums.answer_json::jsonb, event_nums.event_id, subject_id) comEvents
WHERE annums = eventNums
) eu on eu.user_id = s.user_id and s.id = eu.subject_id where 1=1 and s.level = 0
and s.id not in
${subIdList}
and ((vNum.videoNum != s.nums or eu.anNums != eu.eventNums) or(s.nums = 0) )
/*已开始*/
and (eu.anNums !=0 or s.nums !=0) and (vNum.videoNum != s.nums or eu.anNums != eu.eventNums)
/*未开始*/
AND ( eu.anNums = 0 AND s.nums = 0 )
/*已完成*/
and vNum.videoNum is not null and eu.anNums is not null and (vNum.videoNum != 0 or eu.anNums != 0)
AND s.id not in
#{channelId}
and s.master_id = #{masterId} or ( s.available_type = 1 and s.master_id = #{masterId})
and s.create_user = #{createUser} and s.master_id = #{masterId}
ORDER BY s.id desc, s.create_time desc

SELECT

,count(v.id) as videosTotalNum


FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
left join gc_subject sub1 on sub1.fid = s.id
left join gc_video v on v.sub_id = sub1.id
WHERE s.level = #{level} and s.state = #{state}

	AND s.id not in

		#{channelId}



	and s.create_user = #{createUser}

and s.master_id = #{masterId}
GROUP BY s.id, f.id
ORDER BY s.order ASC,s.create_time desc,s.id

SELECT
,concat('[',array_to_string(array_agg(tags.tag_text), ',') ,']') as course_tags FROM gc_subject s left join gc_subject_association subjectAssociation on s.id=subjectAssociation.subject_id or s.fid=subjectAssociation.subject_id left join sys_file f on s.sub_img_id=f.id left join gc_subject_tags tags on tags.subject_id = s.id and ((tags.master_id = #{masterId}) or (tags.master_id != #{masterId} and tags.type = 1)) where subjectAssociation.master_id=#{masterId}
and subjectAssociation.subject_id in
#{subId}
and s.level=0
GROUP BY s.id, subjectAssociation.id, f.id

select count(1) from gc_subject
where


		name=#{name}


		name_index=#{nameIndex}


and master_id = #{masterId} and


		fid is null


		fid = #{fid}



	and id !=#{id}

SELECT

from gc_subject s left join gc_subject s0 on s0.id = s.fid
where s0.master_id = #{masterId} and s0.name_index = #{nameIndex}

select count(1) from gc_subject s
where s.type=#{type} and  s.state!=#{state} and s.sub_id in
(select asso.subject_id from gc_subject_association asso where asso.master_id=#{masterId}

	and asso.subject_id in

		#{subId}


)

select s.*,v.video_name as gcVideo_videoName,v.id as gcVideo_id,f.video_long as gcVideo_long,f.file_type as video_f_file_type, coalesce(max(answer.update_time)) as lastActivityTime,s0.name as sub0Name,s0.Id as sub0Id
from gc_subject s left join gc_subject s0 on s0.id = s.fid left join gc_video v on v.sub_id=s.id left join sys_file f on v.file_id=f.id left join gc_event e on e.video_id=v.id left join gc_user_answer answer on answer.event_id = e.id
left join gc_subject_association ass on s.fid=ass.subject_id and ass.master_id = #{masterId}
where s.fid in
#{subId}
group by s.id, v.id, f.id, s0.Id
order by max(answer.update_time) ${order}
order by s.order asc,s.create_time asc,s.id
order by s.order desc

SELECT gc.*, string_agg(tags.tag_text, ',') as course_tags
FROM gc_subject gc
		 LEFT JOIN gc_subject_tags tags ON tags.subject_id = gc.id AND tags.master_id = #{masterId}
WHERE gc.id = #{id}
GROUP BY gc.id
LIMIT 1

select count(1) from gc_subject
where "level" = 0
  and "state" = #{state}
  and create_user = #{userId}
  and master_id = #{masterId}

SELECT DISTINCT ON (s.id)


FROM gc_subject s
left join gc_content_group_course_assignment cgc on cgc.course_id = s.id
left join gc_access ac ON cgc.content_group_id = ac.id
left join gc_user_access ua on ac.id = ua.access_id and ac.master_id = ua.master_id
left join sys_file f on s.sub_img_id=f.id
where s."level" = 0
and ua.user_id = #{userId}
and s.master_id = #{masterId}
and ua.master_id = #{masterId}


	and s.id not in

		#{ids}



	and s."name" like concat('%',#{name},'%')


	order by s.id ${orderType}, s.create_time ${orderType}

SELECT


FROM gc_subject s
left join sys_file f on s.sub_img_id=f.id
WHERE s."level" = 0


	and s.id not in

		#{ids}



	and s."name" like concat('%',#{name},'%')


	and s.create_user = #{userId}

and s.master_id = #{masterId}

	order by s.create_time ${orderType}

select sub.id
from gc_subject sub where id not in (
	select s.id from gc_user_access ua
		 left join gc_content_group_course_assignment content_group_assignment on content_group_assignment.course_id = ua.access_id AND content_group_assignment.is_mandatory = 1
		 left join gc_subject s on content_group_assignment.course_id = s.id
	where 1=1
	  and s.master_id = #{masterId}
	  and s.create_user = #{createUser}
	  and ua.master_id = #{masterId}
	group by s.id
)
and sub.master_id = #{masterId}
and sub.create_user = #{createUser}

select count(1) from gc_subject where
master_id = #{masterId}
and name_index = #{nameIndex}

select s.id from gc_subject s
where s.create_user = #{userId}
and s.master_id = #{masterId}
and s.state = 1
and s.level = 0

SELECT
FROM gc_subject s JOIN gc_user course_owner ON s.create_user = course_owner.id LEFT JOIN sys_file f ON s.sub_img_id = f.id
LEFT JOIN gc_content_group_course_assignment course_assignement ON s.id = course_assignement.course_id LEFT JOIN gc_user_access user_content_group ON course_assignement.content_group_id = user_content_group.access_id AND user_content_group.user_id = #{userId} AND user_content_group.master_id = #{masterId} WHERE s.master_id = #{masterId} AND s.sub_id IS NULL AND s.name ilike concat('%', #{searchName}, '%') AND (s.create_user = #{userId} OR s.state = 1 OR (s.state = 2 AND user_content_group.id IS NOT NULL));
